/**
 * Generated by Computer — app/intake/result/[id].tsx
 * S-07/08/09/10: Result screen — ID / Pricing / Listings / Export tabs.
 * Loads parsed AI JSON from inventory store and displays it.
 * Source: photo_intake_engine_spec.docx §3.2; TheBeginning_WorkOrder_v1.0.docx §4.7
 */

import { useState } from 'react';
import { View, Text, Pressable, ScrollView, Alert, Clipboard } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useInventoryStore } from '@/store/inventory';
import { useIntakeStore } from '@/store/intake';
import { formatUSD } from '@/lib/pricing';
import { CATEGORY_MAP } from '@/types/categories';

type ResultTab = 'id' | 'pricing' | 'listings' | 'export';

export default function ResultScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const item = useInventoryStore((s) => s.getItemById(id));
  const [tab, setTab] = useState<ResultTab>('id');

  if (!item) {
    return (
      <SafeAreaView className="flex-1 bg-[#0a0a0a] items-center justify-center">
        <Text className="text-[#a1a1aa]">Item not found.</Text>
      </SafeAreaView>
    );
  }

  const cat = CATEGORY_MAP[item.category];

  function handleDone() {
    useIntakeStore.getState().reset();
    router.replace('/(tabs)');
  }

  function copyToClipboard(text: string) {
    Clipboard.setString(text);
    Alert.alert('Copied', 'Copied to clipboard.');
  }

  const exportRow = [
    item.sku,
    item.category,
    item.protocol.toUpperCase(),
    item.confidence + '%',
    item.research?.targetSellPrice ? formatUSD(item.research.targetSellPrice) : '',
    item.research?.minAcceptPrice ? formatUSD(item.research.minAcceptPrice) : '',
    item.status,
    item.createdAt,
  ].join('\t');

  return (
    <SafeAreaView className="flex-1 bg-[#0a0a0a]">
      {/* Header */}
      <View className="px-4 pt-4 pb-3 bg-[#141414] border-b border-[#27272a]">
        <View className="flex-row justify-between items-start mb-1">
          <Text className="text-[#f4f4f5] font-bold text-lg">{item.sku}</Text>
          <ConfidenceBadge confidence={item.confidence} />
        </View>
        <Text className="text-[#a1a1aa] text-sm">{cat.label} · {item.protocol.toUpperCase()}</Text>
      </View>

      {/* Tabs */}
      <View className="flex-row border-b border-[#27272a]">
        {(['id', 'pricing', 'listings', 'export'] as ResultTab[]).map((t) => {
          const labels = { id: 'ID', pricing: 'Pricing', listings: 'Listings', export: 'Export' };
          const enabled = t === 'id' || t === 'export' || (item.protocol === 'core');
          return (
            <Pressable
              key={t}
              onPress={() => enabled && setTab(t)}
              className="flex-1 py-3 items-center"
              style={{ borderBottomWidth: 2, borderBottomColor: tab === t ? '#6366f1' : 'transparent' }}
            >
              <Text
                className="text-sm font-semibold"
                style={{ color: tab === t ? '#6366f1' : enabled ? '#a1a1aa' : '#27272a' }}
              >
                {labels[t]}
              </Text>
            </Pressable>
          );
        })}
      </View>

      <ScrollView className="flex-1 px-4 pt-4" contentContainerStyle={{ paddingBottom: 100 }}>
        {/* ID Tab */}
        {tab === 'id' && (
          <View className="gap-3">
            {Object.entries(item.identification).map(([key, value]) => (
              value !== undefined && value !== '' && (
                <View key={key} className="flex-row justify-between py-2 border-b border-[#1c1c1c]">
                  <Text className="text-[#a1a1aa] text-sm capitalize">{key.replace(/([A-Z])/g, ' $1')}</Text>
                  <Text className="text-[#f4f4f5] text-sm font-medium flex-1 text-right ml-4">
                    {String(value)}
                  </Text>
                </View>
              )
            ))}
            {item.confidenceNotes && (
              <View className="bg-[#f59e0b22] border border-[#f59e0b] rounded-xl p-3 mt-2">
                <Text className="text-[#f59e0b] text-xs font-semibold mb-1">CONFIDENCE NOTE</Text>
                <Text className="text-[#f4f4f5] text-sm">{item.confidenceNotes}</Text>
              </View>
            )}
          </View>
        )}

        {/* Pricing Tab — CORE only */}
        {tab === 'pricing' && item.research && (
          <View className="gap-4">
            {[
              { label: 'Comp 1 (50%)', comp: item.research.comp1, note: 'Recent eBay sold' },
              { label: 'Comp 2 (25%)', comp: item.research.comp2, note: 'Conservative floor' },
              { label: 'Comp 3 (25%)', comp: item.research.comp3, note: 'Optimistic ceiling' },
            ].map(({ label, comp, note }) => (
              <View key={label} className="bg-[#141414] border border-[#27272a] rounded-xl p-4">
                <View className="flex-row justify-between items-start">
                  <Text className="text-[#a1a1aa] text-xs">{label} · {note}</Text>
                  <Text className="text-[#f4f4f5] font-bold text-lg">{formatUSD(comp.price)}</Text>
                </View>
                <Text className="text-[#52525b] text-xs mt-1">{comp.source}{comp.date ? ` · ${comp.date}` : ''}</Text>
              </View>
            ))}
            <View className="bg-[#6366f122] border border-[#6366f1] rounded-xl p-4">
              <View className="flex-row justify-between mb-2">
                <Text className="text-[#a1a1aa] text-sm">Weighted Average</Text>
                <Text className="text-[#f4f4f5] font-bold">{formatUSD(item.research.weightedAvg)}</Text>
              </View>
              <View className="flex-row justify-between mb-2">
                <Text className="text-[#a1a1aa] text-sm">Target Sell Price</Text>
                <Text className="text-[#22c55e] font-bold text-lg">{formatUSD(item.research.targetSellPrice)}</Text>
              </View>
              <View className="flex-row justify-between">
                <Text className="text-[#a1a1aa] text-sm">Min Accept Price</Text>
                <Text className="text-[#f59e0b] font-bold">{formatUSD(item.research.minAcceptPrice)}</Text>
              </View>
            </View>
            <View className="flex-row justify-between items-center bg-[#141414] border border-[#27272a] rounded-xl p-4">
              <Text className="text-[#a1a1aa] text-sm">Velocity Tier</Text>
              <Text className="text-[#6366f1] font-bold">{item.research.velocityTier}</Text>
            </View>
          </View>
        )}

        {/* Listings Tab — CORE only */}
        {tab === 'listings' && item.listings && (
          <View className="gap-4">
            {Object.entries(item.listings).map(([platform, listing]) => listing && (
              <View key={platform} className="bg-[#141414] border border-[#27272a] rounded-xl p-4">
                <View className="flex-row justify-between items-center mb-2">
                  <Text className="text-[#f4f4f5] font-bold capitalize">{platform}</Text>
                  <Text className="text-[#22c55e] font-bold">{formatUSD(listing.price)}</Text>
                </View>
                <Text className="text-[#a1a1aa] text-sm font-semibold mb-1">{listing.title}</Text>
                <Text className="text-[#52525b] text-xs mb-3" numberOfLines={4}>{listing.description}</Text>
                <Pressable
                  onPress={() => copyToClipboard(`${listing.title}\n\n${listing.description}\n\nPrice: ${formatUSD(listing.price)}`)}
                  className="bg-[#1c1c1c] border border-[#27272a] rounded-lg py-2 items-center"
                >
                  <Text className="text-[#6366f1] text-sm font-semibold">Copy Listing</Text>
                </Pressable>
              </View>
            ))}
          </View>
        )}

        {/* Export Tab */}
        {tab === 'export' && (
          <View className="gap-4">
            <View className="bg-[#141414] border border-[#27272a] rounded-xl p-4">
              <Text className="text-[#a1a1aa] text-xs font-semibold tracking-widest mb-2">CLIPBOARD ROW</Text>
              <Text className="text-[#f4f4f5] font-mono text-xs leading-5">{exportRow}</Text>
              <Pressable
                onPress={() => copyToClipboard(exportRow)}
                className="mt-3 bg-[#6366f1] rounded-xl py-3 items-center"
              >
                <Text className="text-white font-bold">Copy Tab-Delimited Row</Text>
              </Pressable>
            </View>
            <Text className="text-[#52525b] text-xs text-center">
              Paste directly into your Reseller Brain OS master sheet.
            </Text>
          </View>
        )}
      </ScrollView>

      {/* Bottom actions */}
      {tab !== 'export' && (
        <View className="absolute bottom-0 left-0 right-0 px-4 pb-8 pt-3 bg-[#0a0a0a] border-t border-[#27272a]">
          <Pressable onPress={handleDone} className="bg-[#22c55e] rounded-2xl py-4 items-center">
            <Text className="text-[#0a0a0a] font-bold text-lg">✓ Saved to Inventory</Text>
          </Pressable>
        </View>
      )}
    </SafeAreaView>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  const color = confidence >= 85 ? '#22c55e' : confidence >= 65 ? '#f59e0b' : '#ef4444';
  const bg = color + '22';
  return (
    <View className="px-3 py-1 rounded-full" style={{ backgroundColor: bg }}>
      <Text className="text-xs font-bold" style={{ color }}>{confidence}% confidence</Text>
    </View>
  );
}
